seq = ""
for line in open("region.fasta"):
    if not line.startswith(">"):
        seq += line.strip().upper()
print(len(seq), seq[:10], seq[-10:])

# GC content
print("GC%", 100*(seq.count('G')+seq.count('C'))/len(seq))

# ORFs on both strands
comp = {'A':'T','T':'A','G':'C','C':'G','N':'N'}
rc = ''.join(comp[c] for c in reversed(seq))
stops = {'TAA','TAG','TGA'}

def orfs(s, label):
    res=[]
    for frame in range(3):
        i=frame
        start=None
        for j in range(frame, len(s)-2, 3):
            cod=s[j:j+3]
            if cod in stops:
                # find preceding ATG
                if start is not None:
                    res.append((start, j+3, j+3-start, label, frame))
                start=None
            elif cod=='ATG' and start is None:
                start=j
        if start is not None:
            res.append((start, len(s), len(s)-start, label, frame))
    return res

