seq = "".join(l.strip() for l in open("region.fasta") if not l.startswith(">")).upper()
n=len(seq)
comp={'A':'T','T':'A','G':'C','C':'G','N':'N'}
def rcomp(s): return ''.join(comp[c] for c in reversed(s))

# find inverted repeats: for each pair of positions i<j, s[i:i+L] == rcomp(s[j:j+L])
best=[]
for L in range(40,10,-1):
    hits=[]
    for i in range(0, n-L):
        a=seq[i:i+L]
        rc=rcomp(a)
        # search for rc after i
        pos=seq.find(rc, i)
        while pos!=-1:
            hits.append((i,pos,L))
            pos=seq.find(rc,pos+1)
    if hits:
        best.extend(hits)
    if len(best)>200 and L<20:
        break
# print longest few
best.sort(key=lambda x:(-x[2], x[0]))
seen=set()
c=0
for i,j,L in best:
    if L>=20:
        print("IR len",L,"left",i,"right",j, seq[i:i+L], "/", seq[j:j+L])
        c+=1
    if c>25: break
print("total IR>=20 hits:", sum(1 for x in best if x[2]>=20))

