seq = "".join(l.strip() for l in open("region.fasta") if not l.startswith(">")).upper()
n=len(seq)
comp={'A':'T','T':'A','G':'C','C':'G','N':'N'}
def rcomp(s): return ''.join(comp[c] for c in reversed(s))

# seed-based imperfect inverted repeat search
K=9
idx={}
for i in range(n-K+1):
    idx.setdefault(seq[i:i+K],[]).append(i)

cands={}
for i in range(n-K+1):
    seed = seq[i:i+K]
    rc = rcomp(seed)
    for j in idx.get(rc,[]):
        if j <= i: continue
        # extend the matching palindrome: compare seq[i-t:i+K+t] with rcomp(seq[j-t:j+K+t])
        t=0
        while i-t-1>=0 and j+K+t<n and seq[i-t-1]==comp[seq[j+K+t]]:
            t+=1
        # total matched length = K + 2t ; mismatches considered = t
        # also extend the other side
        s=0
        while i+K+s<n and j-s-1>=0 and seq[i+K+s]==comp[seq[j-s-1]]:
            s+=1
        total = K + t + s
        # penalty: approximate; report pairs where total>=20
        if total>=20:
            key=(i-t, j-s-1, total)
            cands[key]=total

# collapse overlapping candidates, keep longest
res=sorted(cands.items(), key=lambda kv:-kv[1])
seen=[]
for (i,j,tot),_ in res:
    if any(abs(i-a)<30 and abs(j-b)<30 for a,b,_ in seen): continue
    seen.append((i,j,tot))
print("imperfect IR candidates (>=20bp total match):", len(seen))
for i,j,tot in seen[:20]:
    print("left",i,"right",j,"totalmatch",tot)
    print("  L:",seq[i:i+tot])
    print("  R:",seq[j:j+tot])
